pub fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut it = txt.chars();

    // Empty string => false
    let last = match it.next_back() {
        Some(c) => c,
        None => return false,
    };

    // Last char must be ASCII alphabetic
    if !last.is_ascii_alphabetic() {
        return false;
    }

    // If there is a preceding character, it must be a literal space
    match it.next_back() {
        None => true,           // exactly one character
        Some(prev) => prev == ' ',
    }
}